1	package org.jsoup.select;
2	
3	import org.jsoup.helper.Regex;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.helper.Validate;
6	import org.jsoup.nodes.CDataNode;
7	import org.jsoup.nodes.Comment;
8	import org.jsoup.nodes.DataNode;
9	import org.jsoup.nodes.LeafNode;
10	import org.jsoup.nodes.Node;
11	import org.jsoup.nodes.TextNode;
12	import org.jsoup.parser.TokenQueue;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.function.Function;
16	import java.util.regex.Matcher;
17	import java.util.regex.Pattern;
18	
19	import static org.jsoup.select.StructuralEvaluator.ImmediateParentRun;
20	import static org.jsoup.internal.Normalizer.normalize;
21	
22	/**
23	 * Parses a CSS selector into an Evaluator tree.
24	 */
25	public class QueryParser implements AutoCloseable {
26	    private final static char[] Combinators = {'>', '+', '~'}; // ' ' is also a combinator, but found implicitly
27	    private final static String[] AttributeEvals = new String[]{"=", "!=", "^=", "$=", "*=", "~="};
28	    private final static char[] SequenceEnders = {',', ')'};
29	
30	    private final TokenQueue tq;
31	    private final String query;
32	    private boolean inNodeContext; // ::comment:contains should act on node value, vs element text
33	
34	    /**
35	     * Create a new QueryParser.
36	     * @param query CSS query
37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        return eval;
83	    }
84	
85	    Evaluator parseSelectorGroup() {
86	        // SelectorGroup. Into an Or if > 1 Selector
87	        Evaluator left = parseSelector();
88	        while (tq.matchChomp(',')) {
89	            Evaluator right = parseSelector();
90	            left = or(left, right);
91	        }
92	        return left;
93	    }
94	
95	    Evaluator parseSelector() {
96	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
97	        tq.consumeWhitespace();
98	
99	        Evaluator left;
100	        if (tq.matchesAny(Combinators)) {
101	            // e.g. query is "> div"; left side is root element
102	            left = new StructuralEvaluator.Root();
103	        } else {
104	            left = parseSimpleSequence();
105	        }
106	
107	        while (true) {
108	            char combinator = 0;
109	            if (tq.consumeWhitespace())
110	                combinator = ' ';            // maybe descendant?
111	            if (tq.matchesAny(Combinators)) // no, explicit
112	                combinator = tq.consume();
113	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
114	                break;
115	
116	            if (combinator != 0) {
117	                Evaluator right = parseSimpleSequence();
118	                left = combinator(left, combinator, right);
119	            } else {
120	                break;
121	            }
122	        }
123	        return left;
124	    }
125	
126	    Evaluator parseSimpleSequence() {
127	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
128	        Evaluator left = null;
129	        tq.consumeWhitespace();
130	
131	        // one optional type selector
132	        if (tq.matchesWord() || tq.matches("*|"))
133	            left = byTag();
134	        else if (tq.matchChomp('*'))
135	            left = new Evaluator.AllElements();
136	
137	        // zero or more subclasses (#, ., [)
138	        while(true) {
139	            Evaluator right = parseSubclass();
140	            if (right != null) {
141	                left = and(left, right);
142	            }
143	            else break; // no more simple tokens
144	        }
145	
146	        if (left == null)
147	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
148	        return left;
149	    }
150	
151	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
152	        switch (combinator) {
153	            case '>':
154	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
155	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
156	                run.add(right);
157	                return run;
158	            case ' ':
159	                return and(new StructuralEvaluator.Ancestor(left), right);
160	            case '+':
161	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
162	            case '~':
163	                return and(new StructuralEvaluator.PreviousSibling(left), right);
164	            default:
165	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
166	        }
167	    }
168	
169	    @Nullable Evaluator parseSubclass() {
170	        //  Subclass: ID | Class | Attribute | Pseudo
171	        if      (tq.matchChomp('#'))    return byId();
172	        else if (tq.matchChomp('.'))    return byClass();
173	        else if (tq.matches('['))       return byAttribute();
174	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
175	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
176	        else                            return null;
177	    }
178	
179	    /** Merge two evals into an Or. */
180	    static Evaluator or(Evaluator left, Evaluator right) {
181	        if (left instanceof CombiningEvaluator.Or) {
182	            ((CombiningEvaluator.Or) left).add(right);
183	            return left;
184	        }
185	        return new CombiningEvaluator.Or(left, right);
186	    }
187	
188	    /** Merge two evals into an And. */
189	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
190	        if (left == null) return right;
191	        if (left instanceof CombiningEvaluator.And) {
192	            ((CombiningEvaluator.And) left).add(right);
193	            return left;
194	        }
195	        return new CombiningEvaluator.And(left, right);
196	    }
197	
198	    private Evaluator parsePseudoSelector() {
199	        final String pseudo = tq.consumeCssIdentifier();
200	        switch (pseudo) {
201	            case "lt":
202	                return new Evaluator.IndexLessThan(consumeIndex());
203	            case "gt":
204	                return new Evaluator.IndexGreaterThan(consumeIndex());
205	            case "eq":
206	                return new Evaluator.IndexEquals(consumeIndex());
207	            case "has":
208	                return has();
209	            case "is":
210	                return is();
211	            case "contains":
212	                return contains(false);
213	            case "containsOwn":
214	                return contains(true);
215	            case "containsWholeText":
216	                return containsWholeText(false);
217	            case "containsWholeOwnText":
218	                return containsWholeText(true);
219	            case "containsData":
220	                return containsData();
221	            case "matches":
222	                return matches(false);
223	            case "matchesOwn":
224	                return matches(true);
225	            case "matchesWholeText":
226	                return matchesWholeText(false);
227	            case "matchesWholeOwnText":
228	                return matchesWholeText(true);
229	            case "not":
230	                return not();
231	            case "nth-child":
232	                return cssNthChild(false, false);
233	            case "nth-last-child":
234	                return cssNthChild(true, false);
235	            case "nth-of-type":
236	                return cssNthChild(false, true);
237	            case "nth-last-of-type":
238	                return cssNthChild(true, true);            case "first-child":
239	                return new Evaluator.IsFirstChild();
240	            case "last-child":
241	                return new Evaluator.IsLastChild();
242	            case "first-of-type":
243	                return new Evaluator.IsFirstOfType();
244	            case "last-of-type":
245	                return new Evaluator.IsLastOfType();
246	            case "only-child":
247	                return new Evaluator.IsOnlyChild();
248	            case "only-of-type":
249	                return new Evaluator.IsOnlyOfType();
250	            case "empty":
251	                return new Evaluator.IsEmpty();
252	            case "blank":
253	                return new NodeEvaluator.BlankValue();
254	            case "root":
255	                return new Evaluator.IsRoot();
256	            case "matchText": {
257	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
258	                Evaluator.MatchText matchText = new Evaluator.MatchText();
259	                return matchText;
260	            }
261	            default:
262	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
263	        }
264	    }
265	
266	    // ::comment etc
267	    private Evaluator parseNodeSelector() {
268	        final String pseudo = tq.consumeCssIdentifier();
269	        inNodeContext = true;  // Enter node context
270	
271	        Evaluator left;
272	        switch (pseudo) {
273	            case "node":
274	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
275	                break;
276	            case "leafnode":
277	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
278	                break;
279	            case "text":
280	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
281	                break;
282	            case "comment":
283	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
284	                break;
285	            case "data":
286	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
287	                break;
288	            case "cdata":
289	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
290	                break;
291	            default:
292	                throw new Selector.SelectorParseException(
293	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
294	        }
295	
296	        // Handle following subclasses in node context (like ::comment:contains())
297	        Evaluator right;
298	        while ((right = parseSubclass()) != null) {
299	            left = and(left, right);
300	        }
301	
302	        inNodeContext = false;
303	        return left;
304	    }
305	
306	    private Evaluator byId() {
307	        String id = tq.consumeCssIdentifier();
308	        Validate.notEmpty(id);
309	        return new Evaluator.Id(id);
310	    }
311	
312	    private Evaluator byClass() {
313	        String className = tq.consumeCssIdentifier();
314	        Validate.notEmpty(className);
315	        return new Evaluator.Class(className.trim());
316	    }
317	
318	    private Evaluator byTag() {
319	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
320	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
321	        // consistency - both the selector and the element tag
322	        String tagName = normalize(tq.consumeElementSelector());
323	        Validate.notEmpty(tagName);
324	
325	        // namespaces:
326	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
327	            String plainTag = tagName.substring(2); // strip *|
328	            return new CombiningEvaluator.Or(
329	                new Evaluator.Tag(plainTag),
330	                new Evaluator.TagEndsWith(":" + plainTag)
331	            );
332	        } else if (tagName.endsWith("|*")) { // ns|*
333	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
334	            return new Evaluator.TagStartsWith(ns);
335	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
336	            tagName = tagName.replace("|", ":");
337	        }
338	
339	        return new Evaluator.Tag(tagName);
340	    }
341	
342	    private Evaluator byAttribute() {
343	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
344	            return evaluatorForAttribute(cq);
345	        }
346	    }
347	
348	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
349	        String key = cq.consumeToAny(AttributeEvals); // eq, not, start, end, contain, match, (no val)
350	        key = normalize(key);
351	        Validate.notEmpty(key);
352	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
353	        cq.consumeWhitespace();
354	        final Evaluator eval;
355	
356	        if (cq.isEmpty()) {
357	            if (key.startsWith("^"))
358	                eval = new Evaluator.AttributeStarting(key.substring(1));
359	            else if (key.equals("*")) // any attribute
360	                eval = new Evaluator.AttributeStarting("");
361	            else
362	                eval = new Evaluator.Attribute(key);
363	        } else {
364	            if (cq.matchChomp('='))
365	                eval = new Evaluator.AttributeWithValue(key, cq.remainder());
366	            else if (cq.matchChomp("!="))
367	                eval = new Evaluator.AttributeWithValueNot(key, cq.remainder());
368	            else if (cq.matchChomp("^="))
369	                eval = new Evaluator.AttributeWithValueStarting(key, cq.remainder());
370	            else if (cq.matchChomp("$="))
371	                eval = new Evaluator.AttributeWithValueEnding(key, cq.remainder());
372	            else if (cq.matchChomp("*="))
373	                eval = new Evaluator.AttributeWithValueContaining(key, cq.remainder());
374	            else if (cq.matchChomp("~="))
375	                eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
376	            else
377	                throw new Selector.SelectorParseException(
378	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
379	        }
380	        return eval;
381	    }
382	
383	    //pseudo selectors :first-child, :last-child, :nth-child, ...
384	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
385	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
386	
387	    private Evaluator cssNthChild(boolean last, boolean ofType) {
388	        String arg = consumeParens(); // arg is like "odd", "-n+2", or "2n+1 of .foo .bar"
389	        int ofIdx = indexOfOfClause(arg);
390	        final String formula = normalize(ofIdx < 0 ? arg : arg.substring(0, ofIdx)).replaceAll("\\s+", "");
391	        final int step, offset;
392	        if ("odd".equals(formula)) {
393	            step = 2;
394	            offset = 1;
395	        } else if ("even".equals(formula)) {
396	            step = 2;
397	            offset = 0;
398	        } else {
399	            Matcher stepOffsetM, stepM;
400	            if ((stepOffsetM = NthStepOffset.matcher(formula)).matches()) {
401	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
402	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
403	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
404	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
405	                offset =
406	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
407	            } else if ((stepM = NthOffset.matcher(formula)).matches()) {
408	                step = 0;
409	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
410	            } else {
411	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", formula);
412	            }
413	        }
414	
415	        Evaluator ofSelector = null;
416	        if (ofIdx >= 0) {
417	            if (ofType)
418	                throw new Selector.SelectorParseException(
419	                    "Could not parse query '%s': 'of S' is only supported by :nth-child() and :nth-last-child()", query);
420	            String ofCss = arg.substring(ofIdx + 2).trim(); // skip "of"
421	            if (ofCss.isEmpty())
422	                throw new Selector.SelectorParseException(
423	                    "Could not parse query '%s': :nth-child(An+B of S) requires a selector", query);
424	            ofSelector = parse(ofCss); // full grammar: selector lists, combinators, attributes, nested pseudos
425	        }
426	
427	        if (ofSelector != null)
428	            return last
429	                ? new Evaluator.IsNthLastChildOfSelector(step, offset, ofSelector)
430	                : new Evaluator.IsNthChildOfSelector(step, offset, ofSelector);
431	
432	        return ofType
433	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
434	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
435	    }
436	
437	    /**
438	     Find the index of the {@code of} keyword separating the An+B formula from the of-selector, or -1 if absent.
439	     Only searched before any bracket/paren nesting or quote, as the formula itself is a plain arithmetic token.
440	     */
441	    private static int indexOfOfClause(String arg) {
442	        int depth = 0;
443	        char quote = 0;
444	        boolean escaped = false;
445	        for (int i = 0; i < arg.length(); i++) {
446	            char c = arg.charAt(i);
447	            if (escaped) {
448	                escaped = false;
449	                continue;
450	            }
451	            if (quote != 0) {
452	                if (c == '\\') escaped = true;
453	                else if (c == quote) quote = 0;
454	            } else if (c == '\\') {
455	                escaped = true;
456	            } else if (c == '\'' || c == '"') {
457	                quote = c;
458	            } else if (c == '[' || c == '(') {
459	                depth++;
460	            } else if (c == ']' || c == ')') {
461	                depth--;
462	            } else if (depth == 0 && (c == 'o' || c == 'O') && i + 1 < arg.length()
463	                && (arg.charAt(i + 1) == 'f' || arg.charAt(i + 1) == 'F')
464	                && i > 0 && Character.isWhitespace(arg.charAt(i - 1))
465	                && isOfFollowedByWhitespace(arg, i + 1)) {
466	                return i;
467	            }
468	        }
469	        return -1;
470	    }
471	
472	    // char at f is the 'f' of 'of'; true if only whitespace follows it before the of-selector starts
473	    private static boolean isOfFollowedByWhitespace(String arg, int f) {
474	        int j = f + 1;
475	        while (j < arg.length() && Character.isWhitespace(arg.charAt(j))) j++;
476	        return j > f + 1 && j < arg.length();
477	    }
478	
479	    private String consumeParens() {
480	        return tq.chompBalanced('(', ')');
481	    }
482	
483	    private int consumeIndex() {
484	        String index = consumeParens().trim();
485	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
486	        return Integer.parseInt(index);
487	    }
488	
489	    // pseudo selector :has(el)
490	    private Evaluator has() {
491	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
492	    }
493	
494	    // pseudo selector :is()
495	    private Evaluator is() {
496	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
497	    }
498	
499	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
500	        Validate.isTrue(tq.matchChomp('('), err);
501	        Evaluator eval = parseSelectorGroup();
502	        Validate.isTrue(tq.matchChomp(')'), err);
503	        return func.apply(eval);
504	    }
505	
506	    // pseudo selector :contains(text), containsOwn(text)
507	    private Evaluator contains(boolean own) {
508	        String query = own ? ":containsOwn" : ":contains";
509	        String searchText = TokenQueue.unescape(consumeParens());
510	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
511	
512	        if (inNodeContext)
513	            return new NodeEvaluator.ContainsValue(searchText);
514	
515	        return own
516	            ? new Evaluator.ContainsOwnText(searchText)
517	            : new Evaluator.ContainsText(searchText);
518	    }
519	
520	    private Evaluator containsWholeText(boolean own) {
521	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
522	        String searchText = TokenQueue.unescape(consumeParens());
523	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
524	        return own
525	            ? new Evaluator.ContainsWholeOwnText(searchText)
526	            : new Evaluator.ContainsWholeText(searchText);
527	    }
528	
529	    // pseudo selector :containsData(data)
530	    private Evaluator containsData() {
531	        String searchText = TokenQueue.unescape(consumeParens());
532	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
533	        return new Evaluator.ContainsData(searchText);
534	    }
535	
536	    // :matches(regex), matchesOwn(regex)
537	    private Evaluator matches(boolean own) {
538	        String query = own ? ":matchesOwn" : ":matches";
539	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
540	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
541	        Regex pattern = Regex.compile(regex);
542	
543	        if (inNodeContext)
544	            return new NodeEvaluator.MatchesValue(pattern);
545	
546	        return own
547	            ? new Evaluator.MatchesOwn(pattern)
548	            : new Evaluator.Matches(pattern);
549	    }
550	
551	    // :matches(regex), matchesOwn(regex)
552	    private Evaluator matchesWholeText(boolean own) {
553	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
554	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
555	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
556	
557	        Regex pattern = Regex.compile(regex);
558	        return own
559	            ? new Evaluator.MatchesWholeOwnText(pattern)
560	            : new Evaluator.MatchesWholeText(pattern);
561	    }
562	
563	    // :not(selector)
564	    private Evaluator not() {
565	        String subQuery = consumeParens();
566	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
567	
568	        return new StructuralEvaluator.Not(parse(subQuery));
569	    }
570	
571	    @Override
572	    public String toString() {
573	        return query;
574	    }
575	
576	    @Override
577	    public void close() {
578	        tq.close();
579	    }
580	}
