71	    @Test void negativeExpressionsDontMatchOutOfBounds() {
72	        Document doc = mixedList();
73	        // plain negative constant never matches (positions start at 1)
74	        assertTrue(doc.select("#list :nth-child(-5 of .hit)").isEmpty());
75	        assertTrue(doc.select("#list :nth-last-child(-5 of .hit)").isEmpty());
76	        // -n step never matches
77	        assertTrue(doc.select("#list :nth-child(-1n of .hit)").isEmpty());
78	    }
