import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Selector;
// 1. S with descendant combinator: candidate's own tree scope; hits in other subtrees not counted
Document d = Jsoup.parse(
  "<section><div><em class=t>1</em></div><div><em class=t>2</em><em class=t>3</em></div></section>");
System.out.println("1: " + d.select("section :nth-child(2 of div em.t)").eachText()); // expect [3]
System.out.println("2: " + d.select("section :nth-last-child(1 of div em.t)").eachText()); // expect [1,3]
// 2. adjacent sibling in S
Document d2 = Jsoup.parse("<ul><li class=a>1</li><li class=b>2</li><li class=b>3</li></ul>");
System.out.println("3: " + d2.select("ul :nth-child(1 of li.a + li)").eachText()); // [2]
// 3. root scoping: select rooted at second div; descendant in S must not escape root
var div2 = d2.expectFirst("ul");
System.out.println("4: " + div2.select(":nth-child(2 of li)").eachText()); // [2]
// 4. repeated calls stable
var e = Selector.evaluatorOf("ul :nth-child(odd of li)");
System.out.println("5: " + d2.select(e).eachText() + " / " + d2.select(e).eachText());
// 5. of selector list dedup per-position: same sibling matches two branches
Document d3 = Jsoup.parse("<ul><li class='a b'>x</li><li class=a>y</li></ul>");
System.out.println("6: " + d3.select("ul :nth-child(1 of .a, .b)").eachText()); // [x]
/exit
EOF

